import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import { createTextNode } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{x:number,y:number,z:number}} position
 * @property {{x:number,y:number,z:number}} rotation
 * @property {{x:number,y:number,z:number}} scale
 * @property {{imageUrl:string,depthMapUrl?:string,meshUrl?:string}} assets
 * @property {Array<{name:string,params:any}>} cinematicPrimitives
 * @property {Array<{text:string,role:string}>} textContent
 */

/**
 * @typedef {Object} NodeContext
 * @property {{load:(url:string)=>THREE.Texture}} textureLoader
 * @property {{load:(url:string)=>THREE.Group}} glbLoader
 * @property {{[key:string]:(target:THREE.Object3D,params:any)=>void}} primitives
 * @property {{atlas:any}} fontAtlas
 */

/**
 * Creates a collection card label node.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
	// root container
	const root = new THREE.Object3D();
	root.position.set(config.position.x, config.position.y, config.position.z);
	root.rotation.set(config.rotation.x, config.rotation.y, config.rotation.z);
	root.scale.set(config.scale.x, config.scale.y, config.scale.z);

	/*** BACKGROUND PLANE ***/
	const bgTexture = ctx.textureLoader.load(config.assets.imageUrl);
	const bgMaterial = new MeshBasicNodeMaterial();
	bgMaterial.map = bgTexture;
	bgMaterial.transparent = false;
	// simple unit‑square; UI will scale via parent transforms
	const bgGeometry = new THREE.PlaneGeometry(1, 1);
	const bgMesh = new THREE.Mesh(bgGeometry, bgMaterial);
	bgMesh.position.set(0, 0, 0);
	root.add(bgMesh);

	/*** TEXT LABEL ***/
	// Assuming the first entry in textContent holds the needed string
	const labelSpec = (config.textContent && config.textContent[0]) || { text: 'Collection 2' };
	const textNode = createTextNode(
		{
			text: labelInfo.text,
			font: 'display', // uses Lora per design tokens
			fontWeight: 400,
			size: 0.4, // rough scene‑unit approximation for headline height
			color: new THREE.Color('#16161d'), // ink
			atlasRegion: {
				atlas: 0,
				rect: { x: 0, y: 0, width: 512, height: 320 },
			},
			// slight offset to avoid Z‑fighting with the background plane
			offsetZ: 0.001,
		},
		ctx,
	);
	root.add(textNode);

	/*** CINEMATIC PRIMITIVES ***/
	if (Array.isArray(config.cinematicPrimitives)) {
		for (const prim of config.cinematicPrimitives) {
			const fn = ctx.primitives[prim.name];
			if (typeof fn === 'function') {
				fn(root, prim.params);
			}
		}
	}

	/*** CLEANUP ***/
	const disposables = [bgTexture, bgMaterial, bgGeometry, bgMesh, textNode];
	root.userData.cleanup = () => {
		disposables.forEach((d) => {
			if (d && typeof d.dispose === 'function') d.dispose();
		});
		// kill any GSAP timelines that might have been attached later
		if (root.userData._timeline && typeof root.userData._timeline.kill === 'function') {
			root.userData._timeline.kill();
		}
	};
	// placeholder for event handlers
	root.userData.handlers = {};

	return root;
}
